def make_good_string(n: int, s: str, c: list[int]) -> int:
    zo = [0]
    oz = [0]

    for i in range(n):
        if i % 2:
            if s[i] == '1':
                oz.append(oz[-1] + c[i])
                zo.append(zo[-1])
            else:
                zo.append(zo[-1] + c[i])
                oz.append(oz[-1])
        else:
            if s[i] == '1':
                zo.append(zo[-1] + c[i])
                oz.append(oz[-1])
            else:
                oz.append(oz[-1] + c[i])
                zo.append(zo[-1])

    min_cost = float('inf')
    for i in range(n - 1):
        cost = min(oz[i] + (zo[-1] - zo[i + 1]), zo[i] + (oz[-1] - oz[i + 1]))
        min_cost = min(min_cost, cost)

    return min_cost
